	var args []Node
	for {
		if p.peek().Kind == RParen {
			p.next()
			return args, nil
		}
		arg, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		args = append(args, arg)
		if p.peek().Kind == Comma {
			p.next()
		}
		if p.peek().Kind == RParen {
			p.next()
		}
	}
